cd /workspace && python3 - <<'PY'
import json,subprocess,sys
MAIN='submission/main.py'
def run(doc):
    p=subprocess.run([sys.executable,'-I','-B',MAIN],input=json.dumps(doc).encode(),capture_output=True)
    return p.returncode,(json.loads(p.stdout) if p.returncode==0 else None)
def msg(start,headers,body=b''):
    return (('\r\n'.join([start]+headers)+'\r\n\r\n').encode()+body).hex()

# config with non-canonical alias -> invalid
for name,alias in [('upper host','sip:alice@Lab.Test'),('pct user','sip:%61lice@lab.test'),('tel sep','tel:+1-202-555-0100'),('one label','sip:alice@localhost'),('trailing dot','sip:alice@lab.test.'),('port leading','sip:alice@lab.test:05060'),('ip','sip:alice@1.2.3.4')]:
    cfg={"accounts":[{"id":"alice","default":alias,"aliases":[alias]}],"peers":[{"id":"e","mode":"access","accounts":[]}],"ttl_ms":1,"capacity":1}
    rc,j=run({"version":1,"config":cfg,"events":[]})
    print(name,'rc',rc)

# valid canonical port
cfg={"accounts":[{"id":"alice","default":"sip:alice@lab.test:5060","aliases":["sip:alice@lab.test:5060","sips:alice@lab.test"]}],"peers":[{"id":"e","mode":"access","accounts":[]}],"ttl_ms":1,"capacity":1}
print('valid port/sips rc',run({"version":1,"config":cfg,"events":[]})[0])

# sips target
w=msg('MESSAGE sips:bob@lab.test SIP/2.0',['From: sips:alice@lab.test;tag=t','To: <sips:bob@lab.test>','Call-ID: c','CSeq: 1 MESSAGE','Content-Length: 0'])
rc,j=run({"version":1,"config":cfg,"events":[{"t":0,"peer":"e","auth":"alice","egress":"internal","wire_hex":w}]})
print('sips req',rc,j and j['results'])

# same alias in two accounts -> invalid
cfg={"accounts":[{"id":"a","default":"sip:x@lab.test","aliases":["sip:x@lab.test"]},{"id":"b","default":"sip:x@lab.test","aliases":["sip:x@lab.test"]}],"peers":[{"id":"e","mode":"access","accounts":[]}],"ttl_ms":1,"capacity":1}
print('dup alias rc',run({"version":1,"config":cfg,"events":[]})[0])
PY
